gcWb(){return"\u0641\u0642\u0637 \u062e\u0648\u0627\u0646\u062f\u0647\u200c\u0646\u0634\u062f\u0647"},
gcWa(){return"\u062a\u06cc\u06a9\u062a\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f"},
